export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) throw new TypeError('intervals must be an array');

  const checked = [];
  for (let i = 0; i < intervals.length; i += 1) {
    const pair = intervals[i];
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError(`interval ${i} is not an array of two numbers`);
    }
    if (!Number.isFinite(pair[0]) || !Number.isFinite(pair[1])) {
      throw new TypeError(`interval ${i} has a bound that is not a finite number`);
    }
    if (pair[0] > pair[1]) throw new RangeError(`interval ${i} starts after it ends`);
    checked.push([pair[0], pair[1]]);
  }

  checked.sort((x, y) => x[0] - y[0]);

  const merged = [];
  for (const pair of checked) {
    if (merged.length === 0 || pair[0] > merged[merged.length - 1][1]) {
      merged.push([pair[0], pair[1]]);
      continue;
    }
    const last = merged[merged.length - 1];
    last[1] = Math.max(last[1], pair[1]);
  }
  return merged;
}
